<script setup lang="ts">
import DataTable from '../../components/DataTable.vue'
import type { SessionUser } from '../../stores/session'
type Row = Record<string, string>
type Column = { key: string; label: string }
defineProps<{ selectedBatch: Record<string, any> | null; currentUser: SessionUser | null; busy: boolean; batchTabs: string[]; activeTab: string; rawImports: Record<string, any>[]; batchTransactionRows: Row[]; matchingRows: Row[]; batchExceptionRows: Row[]; batchApprovalRows: Row[]; batchAuditRows: Row[]; tableConfig: Record<string, {columns: Column[]; rows: Row[]}> }>()
const emit = defineEmits<{ matching: []; edit: []; transition: [action: 'cancel' | 'reopen' | 'retry']; submit: []; closeBatch: []; changeTab: [tab: string]; download: [item: Record<string, any>]; downloadErrors: [item: Record<string, any>]; transaction: [row: Row]; exception: [row: Row]; approval: [row: Row] }>()
function formatDate(value?: string) { return value ? new Intl.DateTimeFormat('id-ID', { dateStyle: 'medium', timeZone: 'Asia/Jakarta' }).format(new Date(value)) : '—' }
function badgeClass(value: string) {
  const v = value.toLowerCase()
  if (v.includes('completed') || (v.includes('matched') && !v.includes('unmatched')) || v.includes('aktif') || v.includes('success') || v.includes('disetujui')) return 'badge success'
  if (v.includes('progress') || v.includes('review') || v.includes('menunggu') || v.includes('open')) return 'badge warning'
  if (v.includes('unmatched') || v.includes('only') || v.includes('mismatch') || v.includes('ditolak') || v.includes('failed')) return 'badge danger'
  return 'badge neutral'
}
</script>

<template>
        <section class="detail-page batch-detail-page">

          <div class="detail-title"><div><div class="title-line"><h2>{{ selectedBatch?.batch_no || 'Batch tidak dipilih' }}</h2><span class="badge" :class="badgeClass(selectedBatch?.state || '')">{{ selectedBatch?.state || '—' }}</span></div><p>{{ selectedBatch?.remarks || selectedBatch?.bank_display_name || 'Tanpa catatan' }} <span>·</span> {{ formatDate(selectedBatch?.period_from) }} – {{ formatDate(selectedBatch?.period_to) }} · {{ selectedBatch?.account_code }}</p></div><button v-if="currentUser?.role !== 'OPERATOR' || selectedBatch?.created_by === currentUser?.id" class="button secondary" :disabled="busy" @click="emit('matching')">Hasil Matching</button><button v-if="selectedBatch?.state === 'DRAFT' && currentUser?.role === 'OPERATOR' && selectedBatch?.created_by === currentUser?.id" class="button secondary" :disabled="busy" @click="emit('edit')">Edit Batch</button><button v-if="selectedBatch?.state === 'DRAFT' && currentUser?.role === 'OPERATOR' && selectedBatch?.created_by === currentUser?.id" class="button secondary" :disabled="busy" @click="emit('transition', 'cancel')">Batalkan</button><button v-if="selectedBatch?.state === 'REVIEW' && currentUser?.role === 'OPERATOR' && selectedBatch?.created_by === currentUser?.id" class="button secondary" :disabled="busy" @click="emit('transition', 'reopen')">Koreksi Sumber</button><button v-if="selectedBatch?.state === 'REVIEW' && currentUser?.role === 'OPERATOR' && selectedBatch?.created_by === currentUser?.id" class="button secondary" :disabled="busy" @click="emit('submit')">Ajukan Approval</button><button v-if="selectedBatch?.state === 'FAILED' && currentUser?.role === 'OPERATOR' && selectedBatch?.created_by === currentUser?.id" class="button secondary" :disabled="busy" @click="emit('transition', 'retry')">Coba Matching Lagi</button><button v-if="selectedBatch?.state === 'APPROVED' && currentUser?.role === 'CHECKER'" class="button primary" :disabled="busy" @click="emit('closeBatch')">Tutup Batch</button></div>
          <div class="kpi-grid detail-kpis"><article class="kpi-card"><div class="detail-metric-head"><span class="kpi-top">Transaksi Internal</span><span class="detail-metric-icon teal">↗</span></div><strong>{{ selectedBatch?.internal_count ?? 0 }}</strong><small>Data dari internal</small></article><article class="kpi-card"><div class="detail-metric-head"><span class="kpi-top">Transaksi Bank</span><span class="detail-metric-icon blue">↙</span></div><strong>{{ selectedBatch?.bank_count ?? 0 }}</strong><small>Data dari bank</small></article><article class="kpi-card"><div class="detail-metric-head"><span class="kpi-top">Matched</span><span class="detail-metric-icon green">✓</span></div><strong>{{ selectedBatch?.matched_pairs ?? 0 }}</strong><small>Pasangan transaksi</small></article><article class="kpi-card"><div class="detail-metric-head"><span class="kpi-top">Exceptions Aktif</span><span class="detail-metric-icon amber">!</span></div><strong>{{ selectedBatch?.active_exceptions ?? 0 }}</strong><small>Memerlukan tindak lanjut</small></article></div>
          <article class="panel detail-tabs"><div class="tabs"><button v-for="tab in batchTabs" :key="tab" :class="{ selected: activeTab === tab }" @click="emit('changeTab', tab)">{{ tab }}</button></div><div v-if="activeTab === 'Ringkasan'" class="detail-summary"><div><h3>Ringkasan</h3><p>Ringkasan hasil rekonsiliasi untuk batch ini.</p><div class="match-progress"><span>Matched</span><div><i :style="{ width: `${selectedBatch?.internal_count ? selectedBatch.matched_pairs * 100 / selectedBatch.internal_count : 0}%` }"></i></div><b>{{ selectedBatch?.matched_pairs ?? 0 }} pasangan</b></div><div class="match-progress unmatched-progress"><span>Exceptions</span><div><i :style="{ width: `${selectedBatch?.internal_count ? selectedBatch.active_exceptions * 100 / selectedBatch.internal_count : 0}%` }"></i></div><b>{{ selectedBatch?.active_exceptions ?? 0 }} aktif</b></div></div><div class="batch-state"><span class="state-check">!</span><b>{{ selectedBatch?.state === 'CLOSED' ? 'Batch ditutup' : selectedBatch?.state === 'CANCELLED' ? 'Batch dibatalkan' : selectedBatch?.state === 'DRAFT' ? 'Batch masih dalam persiapan' : selectedBatch?.state === 'PENDING_APPROVAL' ? 'Menunggu persetujuan' : selectedBatch?.state === 'APPROVED' ? 'Siap ditutup' : selectedBatch?.active_exceptions ? 'Belum dapat ditutup' : 'Periksa status batch' }}</b><small>{{ selectedBatch?.state === 'CANCELLED' ? 'Batch ini telah dibatalkan.' : selectedBatch?.state === 'CLOSED' ? 'Hasil rekonsiliasi telah dikunci.' : 'Batch dapat diajukan setelah seluruh data cocok dan tidak ada exception atau approval tertunda.' }}</small></div></div><div v-else-if="activeTab === 'Imports'"><div v-for="item in rawImports" :key="item.id" class="history-item"><span class="file-icon">CSV</span><span class="file-info"><b>{{ item.original_name }}</b><small>{{ item.source_type }} · {{ item.state }} · {{ item.rows_count }} baris · {{ formatDate(item.created_at) }}</small></span><button class="link-button" @click="emit('download', item)">File</button><button v-if="item.has_error_report" class="link-button" @click="emit('downloadErrors', item)">Unduh Error</button></div><div v-if="!rawImports.length" class="detail-empty"><span class="detail-empty-icon">⇧</span><strong>Belum ada file import</strong><p>File yang diunggah untuk batch ini akan ditampilkan di sini.</p></div></div><div v-else-if="activeTab === 'Detail Transaksi'"><DataTable :columns="[{ key: 'ref', label: 'Reference' }, { key: 'date', label: 'Tanggal' }, { key: 'source', label: 'Sumber' }, { key: 'description', label: 'Arah' }, { key: 'debit', label: 'Debit' }, { key: 'credit', label: 'Kredit' }, { key: 'status', label: 'Status' }]" :rows="batchTransactionRows" @open="emit('transaction', $event)" /></div><div v-else-if="activeTab === 'Matching Results'"><DataTable :columns="tableConfig.matching!.columns" :rows="matchingRows" /></div><div v-else-if="activeTab === 'Exceptions'"><DataTable :columns="tableConfig.exceptions!.columns" :rows="batchExceptionRows" link-key="ref" @open="emit('exception', $event)" /></div><div v-else-if="activeTab === 'Approvals'"><DataTable :columns="tableConfig.approvals!.columns" :rows="batchApprovalRows" @open="emit('approval', $event)" /></div><div v-else><DataTable :columns="tableConfig.audit!.columns" :rows="batchAuditRows" /></div></article>
        </section>

</template>
